# owner: platform
"""Lay students out in rows of seats, ordered by last name."""

from typing import List, Sequence

from rosterkit.models import Student


def _sort_key(student: Student):
    return (student.last_name.casefold(), student.first_name.casefold())


def _row_line(number: int, group: Sequence[Student]) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"


# ---
def seating_rows(students: Sequence[Student], seats_per_row: int) -> List[str]:
    """One line per row, students sorted by last name then first name."""
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(students, key=_sort_key)
    starts = range(0, len(ordered), seats_per_row)
    groups = [ordered[start:start + seats_per_row] for start in starts]
    return [_row_line(number, group) for number, group in enumerate(groups, 1)]
