import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make_student(last: str, first: str) -> Student:
    return Student(f"{last}{first}", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_by_last_name_and_split_into_rows(self):
        students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Adler", "Sam")
        ]
        self.assertEqual(
            seating_rows(students, 2),
            ["Row 1: Adler, Sam | Dunmere, Piet", "Row 2: Halloway, Juno"]
        )

    def test_sort_ignores_case_and_breaks_ties_by_first_name(self):
        students = [make_student("smith", "Zed"), make_student("Smith", "Amy")]
        self.assertEqual(seating_rows(students, 5), ["Row 1: Smith, Amy | smith, Zed"])

    def test_zero_or_negative_seats_raise(self):
        students = [make_student("Adler", "Sam")]
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(students, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
EOF
